function moduleMotivation(spec: ModuleSpec): string {
  const override = spec.motivation ?? MODULE_MOTIVATION_OVERRIDES[spec.slug];
  if (override) return override;
  return `${CATEGORY_MOTIVATION[spec.category]} This module focuses that broader problem on **${spec.title}**. Interviewers care because a strong candidate can explain the mechanism in plain language, trace one realistic event from start to finish, and identify the tradeoff or failure mode that changes the answer. After finishing the module, you should be able to explain the core model, use the essential vocabulary accurately, work through a concrete example, and apply the idea in a warmup before moving to harder interview variants.`;
}

type RealLesson = Omit<LessonSeed, "id" | "order">;

function hasLessonSection(markdown: string, heading: string): boolean {
  return new RegExp(`^##\\s+${heading}\\s*$`, "im").test(markdown);
}

function normalizeLessonHeadings(markdown: string): string {
  return markdown
    .replace(/^##\s+why (?:interviewers|interviews) (?:ask|test)(?: it| this| the topic)?\s*$/gim, "## Interview Value")
    .replace(/^##\s+common mistakes\s*$/gim, "## Common Mistakes")
    .replace(/^##\s+common interview questions\s*$/gim, "## Common Interview Questions")
    .replace(/^##\s+examples?\s*$/gim, "## Worked Example")
    .replace(/^##\s+worked examples?\s*$/gim, "## Worked Example")
    .replace(/^##\s+quick checks?\s*$/gim, "## Quick Check")
    .replace(/^##\s+key takeaways?\s*$/gim, "## Key Takeaway")
    .replace(/^##\s+next steps?\s*$/gim, "## Next Steps");
}

function questionAndAnswer(question: string, answer: string): string {
  return `### ${question}\n\n${answer}`;
}

function insertAfterGoal(content: string, addition: string): string {
  const goal = /^##\s+Goal\s*$/im.exec(content);
  if (!goal || goal.index === undefined) return `${addition}\n\n${content}`;
  const afterGoalHeading = goal.index + goal[0].length;
  const nextHeadingOffset = content.slice(afterGoalHeading).search(/^##\s+/m);
  if (nextHeadingOffset === -1) return `${content}\n\n${addition}`;
  const nextHeadingIndex = afterGoalHeading + nextHeadingOffset;
  return `${content.slice(0, nextHeadingIndex).trimEnd()}\n\n${addition}\n\n${content.slice(nextHeadingIndex).trimStart()}`;
}

